renderCats=function(){categories.innerHTML=cats.map(c=>`<button class="category-card ${selectedCat===c?'active':''}" data-cat="${escapeHtml(c)}" onclick="setCat(this.dataset.cat)"><span class="cat-icon">${c==='Todas'?'✨':escapeHtml(iconForCategory(c,window.categoryIcons?.[c]))}</span><strong>${escapeHtml(c)}</strong></button>`).join('')};
render=function(){
 const q=search.value.toLowerCase(),s=size.value,p=Number(priceFilter.value||0);const rows=products.filter(x=>(selectedCat==='Todas'||x.cat===selectedCat)&&(!q||(x.name+' '+x.cat).toLowerCase().includes(q))&&(!s||x.sizes.includes(s))&&(!p||x.price<=p));count.textContent=rows.length+' productos';
 grid.innerHTML=rows.map(x=>{const sold=x.availability==='sold_out',photoCount=x.images?.length||1;return `<article class="card"><div class="photo" onclick="openProduct('${x.id}')"><img loading="lazy" decoding="async" src="${escapeHtml(x.img)}" alt="${escapeHtml(x.name)}">${x.old?'<span class="sale">OFERTA</span>':''}${sold?'<span class="sale sold">AGOTADO</span>':''}<button class="heart" aria-label="Favorito" onclick="event.stopPropagation();toggleFav('${x.id}')">${favs.includes(x.id)?'♥':'♡'}</button>${photoCount>1?`<span class="photo-count">▣ ${photoCount}</span>`:''}<span class="availability-badge ${sold?'sold-out':''}">${sold?'Agotado':'Disponible'}</span></div><div class="card-body"><span class="cat">${escapeHtml(x.cat)}</span><h3>${escapeHtml(x.name)}</h3><div class="price-line"><span class="price">${CLP(x.price)}</span>${x.old?`<span class="old">${CLP(x.old)}</span>`:''}</div><button class="quick" onclick="openProduct('${x.id}')">Ver producto</button></div></article>`}).join('')||'<div class="empty" style="grid-column:1/-1">No encontramos productos con esos filtros.</div>';
};

resolveBusinessForUser=async function(user){
 if(user.id===SUPERADMIN_USER_ID||user.app_metadata?.role==='superadmin'){window.accessExpired=false;const slug=new URLSearchParams(location.search).get('tienda');return slug?await fetchBusiness(slug):null}
 const {data:membership}=await supabaseClient.from('business_members').select('business_id,trial_ends_at').eq('user_id',user.id).eq('active',true).maybeSingle();if(!membership?.business_id)return null;window.accessExpired=Boolean(membership.trial_ends_at&&new Date(membership.trial_ends_at)<=new Date());const {data}=await supabaseClient.from('businesses').select('*').eq('id',membership.business_id).maybeSingle();return data;
};

