function productPhotoSlots(p){const images=(p.images?.length?p.images:[p.image_url]).filter(Boolean).slice(0,3),imageColors=variantOptionsOf(p).image_colors;return `<div class="product-photo-slots">${[0,1,2].map(i=>{const url=images[i]||'';return `<div class="product-photo-slot" data-slot="${i}"><img src="${esc(url||makeImg('Foto '+(i+1),'#eee6ef','#faf7fa'))}" alt="Foto ${i+1}"><div><label for="productImage${i}">${url?'Reemplazar foto '+(i+1):'Agregar foto '+(i+1)}</label><input id="productImage${i}" type="file" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="existing_image_${i}" value="${esc(url)}"><label class="photo-color-field">Color de esta foto<input name="image_color_${i}" list="productColorOptions" value="${esc(imageColors[i]||'')}" placeholder="Ej. Beige"></label><button class="slot-remove" type="button">Quitar</button></div></div>`}).join('')}</div>`}
function renderVariantMatrix(product={}){const form=document.querySelector('#productForm'),matrix=form?.querySelector('#variantMatrix');if(!form||!matrix)return;const present=new Map([...matrix.querySelectorAll('input[data-color]')].map(x=>[normVariant(x.dataset.color)+'|'+normVariant(x.dataset.size),x.checked])),stored=new Map(variantOptionsOf(product).combinations.map(x=>[normVariant(x.color)+'|'+normVariant(x.size),x.availability==='available'])),sizes=list(form.elements.sizes.value);if(!sizes.length)sizes.push('Única');const colors=list(form.elements.colors.value);if(!colors.length)colors.push('Consultar');const availableByDefault=product.availability!=='sold_out';matrix.style.setProperty('--variant-cols',String(sizes.length));matrix.innerHTML=`<div class="variant-row"><strong>Color</strong>${sizes.map(size=>`<span class="variant-head">${esc(size)}</span>`).join('')}</div>${colors.map(color=>`<div class="variant-row"><strong>${esc(color)}</strong>${sizes.map(size=>{const key=normVariant(color)+'|'+normVariant(size),checked=present.has(key)?present.get(key):(stored.has(key)?stored.get(key):availableByDefault);return `<label class="variant-cell"><input type="checkbox" data-color="${esc(color)}" data-size="${esc(size)}" ${checked?'checked':''}><span>${checked?'Disponible':'Agotado'}</span></label>`}).join('')}</div>`).join('')}`;matrix.querySelectorAll('input').forEach(input=>input.onchange=()=>{input.nextElementSibling.textContent=input.checked?'Disponible':'Agotado';updateVariantSummary()});const datalist=form.querySelector('#productColorOptions');if(datalist)datalist.innerHTML=colors.map(color=>`<option value="${esc(color)}">`).join('');updateVariantSummary()}
function updateVariantSummary(){const form=document.querySelector('#productForm'),inputs=[...(form?.querySelectorAll('#variantMatrix input')||[])],available=inputs.filter(x=>x.checked).length;const summary=form?.querySelector('#variantSummary');if(summary)summary.textContent=`${available} combinación${available===1?'':'es'} disponible${available===1?'':'s'} de ${inputs.length}.`}
productForm=function(p={}){
 const panel=adminContent.querySelector('[data-panel=products]');panel.innerHTML=`<form id="productForm" class="admin-grid"><div class="editor-heading"><div><h3>${p.id?'Editar producto':'Nuevo producto'}</h3><p class="help-copy">Relaciona cada fotografía con un color y controla qué combinaciones se pueden comprar.</p></div><button type="button" class="btn btn-outline" onclick="renderProductAdmin()">Volver</button></div><div class="editor-layout"><section class="admin-card"><h3>Información</h3><div class="field"><label for="editName">Nombre</label><input id="editName" name="name" required minlength="2" maxlength="120" value="${esc(p.name)}"></div><div class="field"><label for="editCategory">Categoría</label><select id="editCategory" name="category" required>${[...new Set([...adminCategories.filter(c=>c.active).map(c=>c.name),p.category||'Productos'])].map(name=>`<option value="${esc(name)}" ${name===(p.category||'Productos')?'selected':''}>${esc(name)}</option>`).join('')}</select></div><div class="two-col"><div class="field"><label for="editPrice">Precio</label><input id="editPrice" name="price" type="number" min="0" required value="${esc(p.price??'')}"></div><div class="field"><label for="editOldPrice">Precio anterior</label><input id="editOldPrice" name="old_price" type="number" min="0" value="${esc(p.old_price||'')}"></div></div><div class="field"><label for="editDescription">Descripción y detalles</label><textarea id="editDescription" name="description" maxlength="3000">${esc(p.description)}</textarea></div><div class="two-col"><div class="field"><label for="editSizes">Tallas</label><input id="editSizes" name="sizes" value="${esc((p.sizes||[]).join(', '))}" placeholder="S, M, L"></div><div class="field"><label for="editColors">Colores</label><input id="editColors" name="colors" value="${esc((p.colors||[]).join(', '))}" placeholder="Beige, Negro"></div></div><label><input name="active" type="checkbox" ${p.active!==false?'checked':''}> Visible en la tienda</label></section><aside class="admin-card photo-editor"><h3>Fotos por color</h3><datalist id="productColorOptions"></datalist>${productPhotoSlots(p)}<p class="help-copy">Máximo 3 fotos. Escribe debajo de cada una el color que representa.</p></aside></div><section class="admin-card variant-admin-card"><h3>Disponibilidad por color y talla</h3><p class="help-copy">Marca solamente las combinaciones que pueden comprarse. Las agotadas seguirán visibles.</p><div id="variantMatrix" class="variant-matrix"></div><p id="variantSummary" class="variant-summary"></p></section><p class="profile-message" id="productMessage" role="status"></p><div class="editor-footer"><button type="button" class="btn btn-outline" onclick="renderProductAdmin()">Cancelar</button><button class="btn btn-wine" type="submit">Guardar producto</button></div></form>`;
 document.querySelectorAll('.product-photo-slot').forEach(slot=>{const input=slot.querySelector('input[type=file]'),img=slot.querySelector('img'),hidden=slot.querySelector('input[type=hidden]'),color=slot.querySelector('[name^=image_color_]');input.onchange=()=>{const file=input.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Usa JPG, PNG o WebP de hasta 5 MB');input.value='';return}img.src=URL.createObjectURL(file)};slot.querySelector('.slot-remove').onclick=()=>{input.value='';hidden.value='';color.value='';img.src=makeImg('Foto '+(Number(slot.dataset.slot)+1),'#eee6ef','#faf7fa')}});const form=document.querySelector('#productForm');form.elements.sizes.addEventListener('input',()=>renderVariantMatrix(p));form.elements.colors.addEventListener('input',()=>renderVariantMatrix(p));renderVariantMatrix(p);form.onsubmit=e=>saveProduct(e,p.id);window.scrollTo(0,0);
};

saveProduct=guardedSubmit(async function(e,id){
 e.preventDefault();const form=e.target,f=new FormData(form),message=form.querySelector('#productMessage');message.textContent='Guardando producto…';const images=[],image_colors=[];
 for(let i=0;i<3;i++){let url=String(f.get('existing_image_'+i)||'');const file=form.querySelector('#productImage'+i)?.files[0];if(file){url=await uploadImage(file);if(!url){message.textContent='No se pudo subir la foto '+(i+1)+'.';return}}if(url&&!images.includes(url)){images.push(url);image_colors.push(String(f.get('image_color_'+i)||'').trim())}}
 const sizes=list(f.get('sizes')),colors=list(f.get('colors')),combinations=[...form.querySelectorAll('#variantMatrix input[data-color]')].map(input=>({color:input.dataset.color,size:input.dataset.size,availability:input.checked?'available':'sold_out'})),availability=combinations.some(x=>x.availability==='available')?'available':'sold_out',variant_options={image_colors,combinations};const payload={business_id:managedBusiness.id,name:String(f.get('name')).trim(),category:String(f.get('category')).trim(),price:Number(f.get('price')),old_price:Number(f.get('old_price')||0),availability,stock:availability==='available'?1:0,description:String(f.get('description')).trim(),sizes,colors,images,image_url:images[0]||'',variant_options,active:f.get('active')==='on',updated_at:new Date().toISOString()};
 const result=await (id?supabaseClient.from('products').update(payload).eq('id',id):supabaseClient.from('products').insert(payload));if(result.error){message.textContent=result.error.message;return}toast('Producto guardado');await renderProductAdmin();await loadStore();
});

renderProductAdmin=async function(){
 const panel=adminContent.querySelector('[data-panel=products]');if(!panel||!managedBusiness)return;const {data,error}=await supabaseClient.from('products').select('*').eq('business_id',managedBusiness.id).order('sort_order').order('created_at',{ascending:false});adminProductsCache=data||[];panel.innerHTML='<button class="btn btn-wine" style="width:100%;margin-bottom:12px" onclick="productForm()">＋ Subir producto</button><div class="admin-list" id="adminProductList"></div>';const listEl=panel.querySelector('#adminProductList');if(error){listEl.innerHTML='<div class="notice">'+esc(error.message)+'</div>';return}listEl.innerHTML=adminProductsCache.map((p,i)=>{const sold=!productHasAvailability(p),availableCount=variantOptionsOf(p).combinations.filter(x=>x.availability==='available').length;return `<div class="admin-product"><img src="${esc(p.image_url||p.images?.[0]||makeImg(p.name,'#ead2da','#fff7f9'))}"><div><strong>${esc(p.name)}</strong><div class="price">${CLP(Number(p.price))}</div><small>${p.active?'Visible':'Oculto'} · ${sold?'Agotado':availableCount?availableCount+' variantes disponibles':'Disponible'} · ${esc(p.category)}</small></div><div class="small-actions"><button onclick="productForm(adminProductsCache[${i}])">Editar</button><button onclick="duplicateProductV7(${i})">Duplicar</button><button class="danger" onclick="deleteProduct('${p.id}')">Eliminar</button></div></div><details class="quick-edit"><summary>Edición rápida</summary><div class="quick-fields"><label>Precio <input type="number" min="0" value="${Number(p.price)}"></label><label>Estado <select><option value="available" ${sold?'':'selected'}>Todo disponible</option><option value="sold_out" ${sold?'selected':''}>Todo agotado</option></select></label><label><input type="checkbox" ${p.active?'checked':''}> Visible</label><button type="button" onclick="quickSaveProductV7('${p.id}',this)">Guardar</button><button type="button" ${i===0?'disabled':''} onclick="moveProduct(${i},-1)">Subir</button><button type="button" ${i===adminProductsCache.length-1?'disabled':''} onclick="moveProduct(${i},1)">Bajar</button></div></details>`}).join('')||'<div class="empty">Todavía no hay productos.</div>';
};
async function quickSaveProductV7(id,button){const box=button.closest('.quick-fields'),inputs=box.querySelectorAll('input'),availability=box.querySelector('select').value,product=adminProductsCache.find(p=>p.id===id),options=variantOptionsOf(product);if(options.combinations.length)options.combinations=options.combinations.map(x=>({...x,availability}));const payload={price:Number(inputs[0].value||0),availability,stock:availability==='available'?1:0,variant_options:options,active:inputs[1].checked,updated_at:new Date().toISOString()},result=await supabaseClient.from('products').update(payload).eq('id',id);if(result.error)return toast(result.error.message);toast('Cambios guardados');await renderProductAdmin();await loadStore()}
async function duplicateProductV7(i){const p={...adminProductsCache[i]};delete p.id;delete p.created_at;p.name+=' (copia)';p.active=false;const {error}=await supabaseClient.from('products').insert(p);if(error)return toast(error.message);toast('Producto duplicado como oculto');await renderProductAdmin()}

function ensureImageViewer(){let viewer=document.querySelector('#imageViewer');if(viewer)return viewer;viewer=document.createElement('div');viewer.id='imageViewer';viewer.className='image-viewer';viewer.innerHTML='<button class="viewer-close" aria-label="Cerrar">×</button><img alt="Imagen ampliada"><div class="viewer-controls"><button type="button" data-delta="-.25">−</button><button type="button" data-delta="reset">1:1</button><button type="button" data-delta=".25">＋</button></div>';viewer.querySelector('.viewer-close').onclick=()=>viewer.classList.remove('show');viewer.querySelectorAll('[data-delta]').forEach(btn=>btn.onclick=()=>{const img=viewer.querySelector('img'),delta=btn.dataset.delta;if(delta==='reset')viewer.dataset.zoom='1';else viewer.dataset.zoom=String(Math.max(.5,Math.min(3,Number(viewer.dataset.zoom||1)+Number(delta))));img.style.width=`min(${92*Number(viewer.dataset.zoom)}vw,${900*Number(viewer.dataset.zoom)}px)`});document.body.append(viewer);return viewer}
function openImageViewer(url,alt){const viewer=ensureImageViewer(),img=viewer.querySelector('img');viewer.dataset.zoom='1';img.style.width='min(92vw,900px)';img.src=url;img.alt=alt||'Producto ampliado';viewer.classList.add('show')}
function setProductImage(i){const track=document.querySelector('.pd-main-track'),buttons=[...document.querySelectorAll('.pd-thumb')];track?.scrollTo({left:(track.clientWidth||1)*i,behavior:'smooth'});buttons.forEach((b,j)=>b.classList.toggle('active',i===j))}
function selectedProductVariant(){return {size:productDetail.querySelector('[data-variant=size] .selected')?.dataset.value||'',color:productDetail.querySelector('[data-variant=color] .selected')?.dataset.value||''}}
function selectedProductVariantAvailable(){const {size,color}=selectedProductVariant();return Boolean(size&&color&&combinationAvailable(current,color,size))}
function refreshProductVariantState(){if(!current)return;const options=variantOptionsOf(current),colorBox=productDetail.querySelector('[data-variant=color]'),sizeBox=productDetail.querySelector('[data-variant=size]');if(!colorBox||!sizeBox)return;let color=colorBox.querySelector('.selected')?.dataset.value||current.colors?.[0]||'Consultar';colorBox.querySelectorAll('.chip').forEach(button=>{const available=!options.combinations.length||current.sizes.some(size=>combinationAvailable(current,button.dataset.value,size));button.classList.toggle('variant-sold',!available);button.title=available?'Disponible en alguna talla':'Agotado en todas las tallas'});let size=sizeBox.querySelector('.selected')?.dataset.value||current.sizes?.[0]||'Única';sizeBox.querySelectorAll('.chip').forEach(button=>{const available=combinationAvailable(current,color,button.dataset.value);button.disabled=!available;button.classList.toggle('variant-sold',!available);if(!available&&button.classList.contains('selected')){button.classList.remove('selected');button.setAttribute('aria-pressed','false')}});let selected=sizeBox.querySelector('.selected');if(!selected){selected=[...sizeBox.querySelectorAll('.chip')].find(button=>!button.disabled);if(selected){selected.classList.add('selected');selected.setAttribute('aria-pressed','true')}}size=selected?.dataset.value||size;const available=Boolean(selected&&combinationAvailable(current,color,size)),status=productDetail.querySelector('.stock-state'),add=productDetail.querySelector('#detailAddCart'),whatsapp=productDetail.querySelector('#detailWhatsapp');status.textContent=available?'Disponible · '+color+' / '+size:'Agotado · '+color+(selected?' / '+size:'');status.classList.toggle('sold-out',!available);add.disabled=!available;add.textContent=available?'Agregar al carrito':'Combinación agotada';whatsapp.disabled=!available;whatsapp.textContent=available?'Comprar por WhatsApp':'No disponible'}
function selectProductVariant(button,type,moveImage=true){if(button.disabled)return;const box=button.closest('.chips');box.querySelectorAll('.chip').forEach(item=>{item.classList.remove('selected');item.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');if(type==='color'&&moveImage){const index=variantOptionsOf(current).image_colors.findIndex(color=>normVariant(color)===normVariant(button.dataset.value));if(index>=0)setProductImage(index)}refreshProductVariantState()}
openProduct=function(id){
 current=products.find(p=>String(p.id)===String(id));if(!current)return toast('Este producto ya no está disponible');const images=(current.images?.length?current.images:[current.img]).slice(0,3),options=variantOptionsOf(current),availableColor=current.colors.find(color=>current.sizes.some(size=>combinationAvailable(current,color,size)))||current.colors[0]||'Consultar',variants=(values,type)=>`<div class="chips" data-variant="${type}">${values.map(v=>{const selected=type==='color'&&normVariant(v)===normVariant(availableColor);return `<button class="chip ${type==='color'?'color-chip ':''}${selected?'selected':''}" data-value="${esc(v)}" type="button" onclick="selectProductVariant(this,'${type}')" aria-pressed="${selected}">${type==='color'?`<span class="color-dot" style="--swatch:${esc(colorSwatch(v))}"></span>`:''}${esc(v)}</button>`}).join('')}</div>`;
 productDetail.innerHTML=`<div class="pd-scroll"><div class="pd-layout"><div class="pd-gallery-wrap"><div class="pd-main-track">${images.map((url,i)=>`<button class="pd-main-button" type="button" onclick="openImageViewer((current.images?.length?current.images:[current.img])[${i}],current.name+' foto ${i+1}')"><img loading="eager" src="${esc(url)}" alt="${esc(current.name)} foto ${i+1}"></button>`).join('')}</div>${images.length>1?`<div class="pd-thumbs">${images.map((url,i)=>`<button class="pd-thumb ${i===0?'active':''}" type="button" onclick="setProductImage(${i})"><img src="${esc(url)}" alt="Ver foto ${i+1}">${options.image_colors[i]?`<span class="pd-thumb-label">${esc(options.image_colors[i])}</span>`:''}</button>`).join('')}</div>`:''}</div><div class="pd-info"><p class="eyebrow">${esc(current.cat)}</p><h2>${esc(current.name)}</h2><div class="price-line"><span class="price">${CLP(current.price)}</span>${current.old?`<span class="old">${CLP(current.old)}</span>`:''}</div><p class="stock-state">Disponible</p>${current.desc?`<section class="pd-description-block"><h3>Descripción y detalles</h3><div>${esc(current.desc)}</div></section>`:''}<strong>Color</strong>${variants(current.colors?.length?current.colors:['Consultar'],'color')}<strong>Talla</strong>${variants(current.sizes?.length?current.sizes:['Única'],'size')}</div></div></div><div class="pd-actions"><button class="btn btn-wine" id="detailAddCart">Agregar al carrito</button><button class="wa" id="detailWhatsapp">Comprar por WhatsApp</button></div>`;
 const track=productDetail.querySelector('.pd-main-track');track?.addEventListener('scroll',()=>{const i=Math.round(track.scrollLeft/(track.clientWidth||1));productDetail.querySelectorAll('.pd-thumb').forEach((b,j)=>b.classList.toggle('active',i===j));const mapped=options.image_colors[i],colorButton=[...productDetail.querySelectorAll('[data-variant=color] .chip')].find(button=>normVariant(button.dataset.value)===normVariant(mapped));if(colorButton&&!colorButton.classList.contains('selected'))selectProductVariant(colorButton,'color',false)},{passive:true});productDetail.querySelector('#detailAddCart').onclick=addCart;productDetail.querySelector('#detailWhatsapp').onclick=directWhatsapp;productModal.classList.add('show');productDetail.querySelector('.pd-scroll').scrollTop=0;const initialColorButton=[...productDetail.querySelectorAll('[data-variant=color] .chip')].find(button=>button.classList.contains('selected'));if(initialColorButton){const imageIndex=options.image_colors.findIndex(color=>normVariant(color)===normVariant(initialColorButton.dataset.value));if(imageIndex>=0)setProductImage(imageIndex)}refreshProductVariantState();
};
addCart=function(){if(!current)return toast('Selecciona un producto');if(!selectedProductVariantAvailable())return toast('Esta combinación está agotada');const {size:selectedSize,color:selectedColor}=selectedProductVariant(),key=current.id+'|'+selectedSize+'|'+selectedColor,row=cart.find(x=>x.key===key),imageIndex=variantOptionsOf(current).image_colors.findIndex(color=>normVariant(color)===normVariant(selectedColor)),image=current.images?.[imageIndex]||current.img;if(row)row.qty=Number(row.qty||0)+1;else cart.push({key,id:current.id,name:current.name,price:Number(current.price),img:image,size:selectedSize,color:selectedColor,qty:1});save();closeModal('productModal');openCart();toast('Producto agregado al carrito')};
function orderProductEmoji(product){
 const value=String((product?.name||'')+' '+(product?.cat||product?.category||'')).toLowerCase();
 if(value.includes('corazón')||value.includes('corazon'))return '❤️';
 if(value.includes('falda')||value.includes('vestido'))return '👗';
 if(value.includes('polera')||value.includes('blusa')||value.includes('camisa'))return '👚';
 if(value.includes('zapato')||value.includes('calzado'))return '👠';
 if(value.includes('cintur')||value.includes('cartera')||value.includes('bolso'))return '👜';
 if(value.includes('chaqueta')||value.includes('abrigo'))return '🧥';
 return '✨';
}
function buildWhatsappOrder(items,customer={}){
 const store=String(activeBusiness?.name||'la tienda').toLocaleUpperCase('es-CL'),name=customer.name||'Sin indicar',commune=customer.commune||'Sin indicar',notes=customer.notes||'Sin observaciones';
 const productsText=items.map(x=>`${orderProductEmoji(x)} *${x.name}*\n• Talla: ${x.size||'Única'}\n• Color: ${x.color||'Consultar'}\n• Cantidad: ${Number(x.qty||1)}\n• Precio: ${CLP(Number(x.price||0)*Number(x.qty||1))}`).join('\n\n');
 const total=items.reduce((sum,x)=>sum+Number(x.price||0)*Number(x.qty||1),0);
 return `🛍️ *NUEVO PEDIDO — ${store}*\n\nHola 👋 Quiero realizar el siguiente pedido:\n\n━━━━━━━━━━━━━━\n🛒 *PRODUCTOS*\n\n${productsText}\n\n━━━━━━━━━━━━━━\n💰 *TOTAL: ${CLP(total)}*\n━━━━━━━━━━━━━━\n\n👤 *Cliente:* ${name}\n📍 *Comuna:* ${commune}\n📝 *Observaciones:* ${notes}\n\n✅ Quedo atento/a a la confirmación de disponibilidad y coordinación del pedido. ¡Gracias!`;
}
orderWhatsapp=function(){
 if(!cart.length)return toast('Tu carrito está vacío');const number=(activeBusiness?.whatsapp||'').replace(/\D/g,'');if(!number)return toast('El negocio aún no configuró WhatsApp');
 const customer={name:document.querySelector('#buyerName')?.value.trim()||'Sin indicar',commune:document.querySelector('#buyerCommune')?.value.trim()||'Sin indicar',notes:document.querySelector('#buyerNotes')?.value.trim()||'Sin observaciones'};
 window.open('https://wa.me/'+number+'?text='+encodeURIComponent(buildWhatsappOrder(cart,customer)),'_blank');
};
directWhatsapp=function(){
 if(!current||!selectedProductVariantAvailable())return toast('Esta combinación está agotada');const {size,color}=selectedProductVariant(),number=(activeBusiness?.whatsapp||'').replace(/\D/g,'');if(!number)return toast('El negocio aún no configuró WhatsApp');
 window.open('https://wa.me/'+number+'?text='+encodeURIComponent(buildWhatsappOrder([{...current,size,color,qty:1}],{})),'_blank');
};

renderProfiles=async function(){
 const panel=adminContent.querySelector('[data-panel=profiles]');if(!panel)return;const [{data:businesses,error},{data:members}]=await Promise.all([supabaseClient.from('businesses').select('*').order('created_at',{ascending:false}),supabaseClient.from('business_members').select('user_id,username,role,active,trial_ends_at,business_id').order('created_at',{ascending:false})]);if(error){panel.innerHTML='<div class="notice">'+esc(error.message)+'</div>';return}window.profileMembers=members||[];
 window.businessPages=businesses||[];panel.innerHTML=`<form id="createProfileForm" class="admin-grid"><div class="admin-card"><h3>Crear página y perfil</h3><div class="field"><label>Nombre del negocio</label><input name="businessName" required></div><div class="field"><label>Usuario</label><input name="username" pattern="[a-zA-Z0-9._-]{3,30}" required></div><div class="field"><label>Contraseña</label><input name="password" type="password" minlength="6" required></div><div class="field"><label>Nombre del enlace</label><input name="slug" placeholder="se completa automáticamente"></div></div><p class="profile-message" id="profileCreateMessage"></p><button class="btn btn-wine">Crear perfil y página</button></form><h3 style="margin-top:24px">Páginas creadas</h3><div class="admin-list">${(businesses||[]).map(b=>{const people=(members||[]).filter(m=>m.business_id===b.id);return `<div class="admin-card admin-business-card"><div><strong>${esc(b.name)}</strong><div class="share-link">${esc(appBaseUrl+'?tienda='+b.slug)}</div><small>${b.published?'Pública':'No publicada'} · ${people.length} perfil${people.length===1?'':'es'}</small></div><div class="small-actions"><button onclick="manageBusiness('${b.id}')">Editar página</button><button onclick="location.href='?tienda=${encodeURIComponent(b.slug)}'">Ver</button></div><div>${people.map(m=>`<div class="access-controls"><strong>Usuario: ${esc(m.username)}</strong><label>Vencimiento <input type="date" value="${m.trial_ends_at?m.trial_ends_at.slice(0,10):''}"></label>${m.user_id!==SUPERADMIN_USER_ID?`<div class="small-actions"><button onclick="manageMemberAccess('${m.user_id}',${m.active},this.closest('.access-controls').querySelector('input').value)">Guardar acceso</button><button onclick="resetMemberPassword('${m.user_id}')">Cambiar contraseña</button><button onclick="toggleMember('${m.user_id}','${b.id}',${!m.active})">${m.active?'Suspender':'Activar'}</button></div>`:'<small>Superadministrador</small>'}</div>`).join('')}</div><div class="small-actions business-danger"><button class="danger" onclick="deleteBusinessPage('${b.id}')">Eliminar página</button></div></div>`}).join('')||'<div class="empty">Todavía no hay páginas.</div>'}</div>`;
 const form=panel.querySelector('#createProfileForm');form.onsubmit=createProfile;const businessName=form.elements.businessName,slug=form.elements.slug;businessName.oninput=()=>{if(!slug.dataset.edited)slug.value=slugFrom(businessName.value)};slug.oninput=()=>slug.dataset.edited='1';
};
async function deleteBusinessPage(id){const name=window.businessPages?.find(b=>b.id===id)?.name||'esta página';if(!confirm(`¿Eliminar definitivamente la página “${name}”? Se eliminarán sus productos, categorías, imágenes y perfiles. Esta acción no se puede deshacer.`))return;const typed=prompt('Para confirmar, escribe ELIMINAR');if(typed!=='ELIMINAR')return toast('Eliminación cancelada');const {data,error}=await supabaseClient.functions.invoke('manage-business-admin',{body:{action:'delete_business',businessId:id}});if(error||data?.error)return toast(data?.error||error.message);if(managedBusiness?.id===id)managedBusiness=null;toast('Página eliminada');await renderProfiles();if(isPortalHome())await renderBusinessPortal()}
